-- CipherMesh: operational ISMS records (ADR-016, CM-T088; docs/security/isms-operations.md).
-- Generated by `prisma migrate diff` from schema.prisma, then reviewed, plus hand-written parts:
--   checks          the status is one of its kind's documented statuses; the code number, the
--                   version and the content shape (a JSON object) are valid; times are ordered.
--   record guard    kind, number, creator and creation time are write-once; every change raises
--                   the version by exactly one; a final status (accepted, completed, closed,
--                   recorded, withdrawn) never changes again, except that an exercise can always
--                   be withdrawn.
--   activity        append-only for every role, like audit_events (20261002000200), but it is an
--                   ordinary authenticated history, not the hash-chained ledger of ADR-009 (L-81).
--   grants          cm_api SELECT, INSERT, UPDATE on isms_records and SELECT, INSERT on
--                   isms_activity; cm_worker and cm_verifier nothing. Nobody can DELETE either.
-- The workflow conditions themselves (section 6 to 13 of the manual) are enforced by the API inside
-- the transaction that locks the record; these constraints make a skipped or silent change
-- impossible even for a faulty writer.

-- CreateEnum
CREATE TYPE "IsmsRecordKind" AS ENUM ('RISK_ASSESSMENT', 'CONTROL_VERIFICATION', 'AUDIT', 'FINDING', 'MANAGEMENT_REVIEW', 'SCOPE_REVIEW', 'POLICY_REVIEW', 'INCIDENT');

-- CreateTable
CREATE TABLE "isms_records" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "kind" "IsmsRecordKind" NOT NULL,
    "seq" INTEGER NOT NULL,
    "ref" VARCHAR(400) NOT NULL,
    "status" VARCHAR(40) NOT NULL,
    "data" JSONB NOT NULL,
    "version" INTEGER NOT NULL DEFAULT 1,
    "exercise" BOOLEAN NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL,
    "created_by_id" UUID NOT NULL,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,
    "updated_by_id" UUID NOT NULL,

    CONSTRAINT "isms_records_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "isms_activity" (
    "id" BIGSERIAL NOT NULL,
    "record_id" UUID NOT NULL,
    "action" VARCHAR(40) NOT NULL,
    "from_status" VARCHAR(40),
    "to_status" VARCHAR(40) NOT NULL,
    "rationale" VARCHAR(4000),
    "snapshot" JSONB NOT NULL,
    "actor_id" UUID NOT NULL,
    "at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "isms_activity_pkey" PRIMARY KEY ("id")
);

