-- Hand-written constraints (new tables, no existing rows).
ALTER TABLE "isms_records" ADD CONSTRAINT "isms_records_status_check" CHECK (
  ("kind" = 'RISK_ASSESSMENT' AND "status" IN ('ASSESSED', 'TREATMENT_PLANNED', 'TREATMENT_VERIFIED', 'RESIDUAL_ACCEPTED', 'WITHDRAWN'))
  OR ("kind" = 'CONTROL_VERIFICATION' AND "status" IN ('RECORDED', 'WITHDRAWN'))
  OR ("kind" = 'AUDIT' AND "status" IN ('PLANNED', 'IN_PROGRESS', 'COMPLETED', 'WITHDRAWN'))
  OR ("kind" = 'FINDING' AND "status" IN ('OPEN', 'ANALYZED', 'ACTION_PLANNED', 'ACTION_IMPLEMENTED', 'AWAITING_EFFECTIVENESS', 'CLOSED', 'WITHDRAWN'))
  OR ("kind" = 'MANAGEMENT_REVIEW' AND "status" IN ('DRAFT', 'RECORDED', 'WITHDRAWN'))
  OR ("kind" IN ('SCOPE_REVIEW', 'POLICY_REVIEW') AND "status" IN ('RECORDED', 'WITHDRAWN'))
  OR ("kind" = 'INCIDENT' AND "status" IN ('OPEN', 'CONTAINED', 'RESOLVED', 'CLOSED', 'WITHDRAWN'))
);
ALTER TABLE "isms_records" ADD CONSTRAINT "isms_records_shape_check" CHECK (
  "seq" BETWEEN 1 AND 999999
  AND "version" >= 1
  AND jsonb_typeof("data") = 'object'
  AND "updated_at" >= "created_at"
);
ALTER TABLE "isms_activity" ADD CONSTRAINT "isms_activity_shape_check" CHECK (
  jsonb_typeof("snapshot") = 'object' AND "action" ~ '^[a-z_]{3,40}$'
);

CREATE FUNCTION "cm_guard_isms_record_change"() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  IF NEW."kind" IS DISTINCT FROM OLD."kind" OR NEW."seq" IS DISTINCT FROM OLD."seq"
     OR NEW."created_at" IS DISTINCT FROM OLD."created_at"
     OR NEW."created_by_id" IS DISTINCT FROM OLD."created_by_id"
     OR NEW."exercise" IS DISTINCT FROM OLD."exercise" THEN
    RAISE EXCEPTION 'isms_records: identity columns are write-once'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."version" <> OLD."version" + 1 THEN
    RAISE EXCEPTION 'isms_records: every change raises the version by exactly one'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."status" IN ('RESIDUAL_ACCEPTED', 'COMPLETED', 'CLOSED', 'RECORDED', 'WITHDRAWN') THEN
    -- A final record changes only by the withdrawal of an exercise.
    IF NOT (OLD."exercise" AND OLD."status" <> 'WITHDRAWN' AND NEW."status" = 'WITHDRAWN') THEN
      RAISE EXCEPTION 'isms_records: a final record does not change'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW."status" = 'WITHDRAWN' AND OLD."status" <> 'WITHDRAWN' AND NOT OLD."exercise" THEN
    RAISE EXCEPTION 'isms_records: only exercise records can be withdrawn'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "isms_records_guard"
  BEFORE UPDATE ON "isms_records"
  FOR EACH ROW EXECUTE FUNCTION "cm_guard_isms_record_change"();

CREATE FUNCTION "cm_reject_isms_activity_modification"() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
  RAISE EXCEPTION 'isms_activity is append-only: % is not allowed', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER "isms_activity_reject_update_delete"
  BEFORE UPDATE OR DELETE ON "isms_activity"
  FOR EACH ROW EXECUTE FUNCTION "cm_reject_isms_activity_modification"();

CREATE TRIGGER "isms_activity_reject_truncate"
  BEFORE TRUNCATE ON "isms_activity"
  FOR EACH STATEMENT EXECUTE FUNCTION "cm_reject_isms_activity_modification"();

-- Trigger functions are not callable by runtime roles (as in 20261002000300_runtime_role_grants).
REVOKE ALL ON FUNCTION "cm_guard_isms_record_change"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "cm_reject_isms_activity_modification"() FROM PUBLIC;

-- Grants: the API records and reads; nothing else touches the ISMS tables.
REVOKE ALL ON "isms_records", "isms_activity" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "isms_records" TO cm_api;
GRANT SELECT, INSERT ON "isms_activity" TO cm_api;
GRANT USAGE ON SEQUENCE "isms_activity_id_seq" TO cm_api;
